import{_ as e,o as i,c as n,a2 as s}from"./chunks/framework.BXzK3EA4.js";const t="/assets/cec62239767828bf.cSNT0bVW.png",a="/assets/3fbbf14cb6c0dada.D9NPt0ke.png",l="/assets/b2afc1b626d94611.CXqWCanG.png",b=JSON.parse('{"title":"linux系统如何设置开启/禁止ping","description":"","frontmatter":{"title":"linux系统如何设置开启/禁止ping"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/linux/enable-disable-ping.md","filePath":"ops-knowledge-base/operating-system/linux/enable-disable-ping.md","lastUpdated":1788259091000}'),o={name:"ops-knowledge-base/operating-system/linux/enable-disable-ping.md"};function c(g,p,r,_,P,d){return i(),n("div",null,[...p[0]||(p[0]=[s('<p>为了防止别人通过网络ping扫描找到并攻击机，可以在本机设置禁止停止ping命令</p><p>L inux默认是允许Ping响应的，系统是不允许Ping由2个原因决定的：</p><ul><li>内核参数</li><li>防火墙</li></ul><p>需要2个因素同时允许才能允许Ping ，2个因素有任意一个禁止Ping就无法Ping</p><p>一.内核禁Ping的设置方法</p><p>首先我们可以先查看一下IP是否正常通信，这里推荐ping.pe网站，输入IP测试连通性，可以查看到目标IP是允许Ping的。</p><p><img src="'+t+'" alt=""></p><p>临时禁Ping ：</p><p>echo 1 &gt;/proc/sys/net/ipv4/ icmp_echo_ignore_all   #设置临时禁止Ping</p><p>这个时候我们再查IP已经禁Ping了，如果这个时候我们再想测试IP连通性，我们可以对端口进行Ping测试</p><p>这里可以看到是可以连通的，因为是临时禁Ping ，所以机器重启后会修复Ping功能</p><p><img src="'+a+'" alt=""><img src="'+l+'" alt=""></p><p>永久禁Ping ：</p><p>#vi /etc/sysctl.conf #进入配置文件</p><p>在里面添加一行：net.ipv4.icmp _echo_ignore_all= 1</p><p>如果已经有net.ipv4.icmp _echo_ignore_all这一步了，直接修改=号码后面板的值即可能的。（0表示允许，1表示禁止）</p><h2 id="sysctl-p-应用新配置" tabindex="-1">sysctl -p #应用新配置 <a class="header-anchor" href="#sysctl-p-应用新配置" aria-label="Permalink to &quot;sysctl -p    #应用新配置&quot;">​</a></h2><p>查看是否禁止ping</p><p>cat /proc/sys/net/ipv4/icmp_echo_ignore_all</p><p>内容为1 禁止停止ping 内容为0 开启ping</p>',20)])])}const u=e(o,[["render",c]]);export{b as __pageData,u as default};
